import 'package:firebase_auth/firebase_auth.dart';
import 'package:intl/intl.dart';
import '../../../core/constants/app_colors.dart';
import '../../../core/constants/locale_controller.dart';
import '../../../services/booking_service.dart';
import '../../../services/user_service.dart';
import '../../shared/models/booking.dart';
import '../../shared/models/app_user.dart';

class CurrentShiftScreen extends StatefulWidget{final String? bookingId;const CurrentShiftScreen({super.key,this.bookingId});@override State<CurrentShiftScreen> createState()=>_CurrentShiftScreenState();}
class _CurrentShiftScreenState extends State<CurrentShiftScreen>{Booking? _booking;AppUser? _client;bool _loading=true,_checkedIn=false,_checkedOut=false,_processing=false;String? _error;bool get en=>LocaleController.instance.isEnglish;String tx(String ar,String english)=>en?english:ar;
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{if(mounted)setState((){_loading=true;_error=null;});try{final user=FirebaseAuth.instance.currentUser;if(user==null){if(mounted)setState(()=>_error=tx('يرجى تسجيل الدخول','Please log in'));return;}Booking? booking;if(widget.bookingId?.isNotEmpty==true){booking=await BookingService().getBooking(widget.bookingId!);}else{final s=await FirebaseFirestore.instance.collection('bookings').where('nurseId',isEqualTo:user.uid).where('status',whereIn:['confirmed','in_progress']).orderBy('createdAt',descending:true).limit(1).get();if(s.docs.isNotEmpty)booking=Booking.fromFirestore(s.docs.first);}if(booking!=null){final client=await UserService().getUser(booking.clientId);if(mounted)setState((){_booking=booking;_client=client;_checkedIn=booking!.status=='in_progress';_checkedOut=booking.status=='completed';});}}catch(_){if(mounted)setState(()=>_error=tx('حدث خطأ أثناء تحميل الشيفت','Unable to load the current shift'));}finally{if(mounted)setState(()=>_loading=false);}}
 Future<void> _checkIn()async{setState(()=>_processing=true);try{await BookingService().checkInShift(_booking!.id);if(mounted){setState((){_checkedIn=true;_booking=_booking!.copyWith(status:'in_progress');});_message(tx('تم تسجيل الحضور','Check-in recorded'));}}catch(_){if(mounted)setState(()=>_error=tx('خطأ في تسجيل الحضور','Check-in failed'));}finally{if(mounted)setState(()=>_processing=false);}}
 Future<void> _checkOut()async{setState(()=>_processing=true);try{await BookingService().checkOutShift(_booking!.id);if(mounted){setState((){_checkedOut=true;_booking=_booking!.copyWith(status:'completed');});_message(tx('تم تسجيل الانصراف','Check-out recorded'));}}catch(_){if(mounted)setState(()=>_error=tx('خطأ في تسجيل الانصراف','Check-out failed'));}finally{if(mounted)setState(()=>_processing=false);}}
 void _message(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 @override Widget build(BuildContext context){final locale=en?'en_US':'ar_EG';return Scaffold(backgroundColor:AppColors.background,appBar:AppBar(title:Text(tx('الشيفت الحالي','Current shift'))),body:_loading?const Center(child:CircularProgressIndicator()):_error!=null&&_booking==null?Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(_error!,style:const TextStyle(color:AppColors.error)),const SizedBox(height:16),ElevatedButton(onPressed:_load,child:Text(tx('إعادة المحاولة','Retry')))])):_booking==null?Center(child:Text(tx('لا يوجد شيفت حالياً','No current shift'))):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[CircleAvatar(radius:26,backgroundColor:AppColors.primaryLight,backgroundImage:(_client?.photoUrl?.isNotEmpty??false)?NetworkImage(_client!.photoUrl!):null,child:(_client?.photoUrl?.isNotEmpty??false)?null:const Icon(Icons.person_outline)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_client?.name.trim().isNotEmpty==true?_client!.name.trim():tx('العميل','Client'),style:const TextStyle(fontWeight:FontWeight.w700,fontSize:16)),if(_client?.phone.isNotEmpty??false)Text(_client!.phone,style:const TextStyle(color:AppColors.textSecondary))])),IconButton(tooltip:tx('مراسلة العميل','Message client'),onPressed:()=>context.push('/nurse/chat/${_booking!.id}'),icon:const Icon(Icons.chat_bubble_outline,color:AppColors.primary))])),const SizedBox(height:16),Container(padding:const EdgeInsets.symmetric(horizontal:12,vertical:6),decoration:BoxDecoration(color:_booking!.status=='in_progress'?Colors.green:_booking!.status=='confirmed'?Colors.blue:Colors.grey,borderRadius:BorderRadius.circular(8)),child:Text(_booking!.status=='in_progress'?tx('جاري','In progress'):tx('قادم','Upcoming'),style:const TextStyle(color:Colors.white))),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[_row(tx('رقم الحجز','Booking number'),_booking!.id.length>8?_booking!.id.substring(0,8):_booking!.id),_row(tx('التاريخ','Date'),DateFormat.yMMMd(locale).format(_booking!.shiftStart)),_row(tx('البداية','Start'),DateFormat.jm(locale).format(_booking!.shiftStart)),_row(tx('النهاية','End'),DateFormat.jm(locale).format(_booking!.shiftEnd)),_row(tx('المدة','Duration'),'${_booking!.shiftHours} ${tx('ساعة','hrs')}'),_row(tx('السعر','Price'),'${_booking!.totalAmount} ${tx('ج.م','EGP')}')]))),const SizedBox(height:24),if(_checkedOut)Center(child:Text(tx('تم الانتهاء من الشيفت','Shift completed'),style:const TextStyle(color:AppColors.success,fontSize:18))),if(!_checkedOut&&_booking!.status=='confirmed')SizedBox(width:double.infinity,child:ElevatedButton(onPressed:_processing?null:_checkIn,child:_processing?const SizedBox(width:20,height:20,child:CircularProgressIndicator(color:Colors.white,strokeWidth:2)):Text(tx('تسجيل الحضور (Check-in)','Check in'))),if(_checkedIn&&!_checkedOut)SizedBox(width:double.infinity,child:ElevatedButton(onPressed:_processing?null:_checkOut,style:ElevatedButton.styleFrom(backgroundColor:Colors.orange),child:_processing?const SizedBox(width:20,height:20,child:CircularProgressIndicator(color:Colors.white,strokeWidth:2)):Text(tx('تسجيل الانصراف (Check-out)','Check out')))]));}
 Widget _row(String label,String value)=>Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(label,style:const TextStyle(fontWeight:FontWeight.bold)),Text(value)]));
}
